import socket, sys, binascii, struct, threading, os

def enc_name(n):
    if n in ("", "."): return b"\x00"
    out=b""
    for lab in n.rstrip(".").split("."):
        b=lab.encode()
        out+=bytes([len(b)])+b
    return out+b"\x00"

class Resp:
    def __init__(self):
        self.flags=0x8180; self.q=[]; self.an=[]; self.ns=[]; self.ar=[]; self.txid=None
    def question(self,name,t,c=1): self.q.append((name,t,c))
    def add(self,sec,name,t,c,ttl,rdata): getattr(self,sec).append((name,t,c,ttl,rdata))
    def build(self, txid):
        tid = self.txid if self.txid is not None else txid
        out=struct.pack(">HHHHHH",tid,self.flags,len(self.q),len(self.an),len(self.ns),len(self.ar))
        for (n,t,c) in self.q: out+=enc_name(n)+struct.pack(">HH",t,c)
        for sec in (self.an,self.ns,self.ar):
            for (n,t,c,ttl,rd) in sec:
                out+=enc_name(n)+struct.pack(">HHIH",t,c,ttl,len(rd))+rd
        return out

def serve(build_fn, port=5353, count=1, proto="udp", show=True):
    if proto=="udp":
        s=socket.socket(socket.AF_INET,socket.SOCK_DGRAM)
        s.setsockopt(socket.SOL_SOCKET,socket.SO_REUSEADDR,1)
        s.bind(("127.0.0.1",port)); s.settimeout(10)
        for i in range(count):
            data,addr=s.recvfrom(65535)
            if show: print("QUERY:",binascii.hexlify(data).decode(),file=sys.stderr)
            txid=struct.unpack(">H",data[:2])[0]
            r=build_fn(data,txid)
            if r is not None: s.sendto(r,addr)
        s.close()
    else:
        s=socket.socket(socket.AF_INET,socket.SOCK_STREAM)
        s.setsockopt(socket.SOL_SOCKET,socket.SO_REUSEADDR,1)
        s.bind(("127.0.0.1",port)); s.listen(5); s.settimeout(10)
        for i in range(count):
            c,addr=s.accept()
            ln=struct.unpack(">H",c.recv(2))[0]
            data=c.recv(ln)
            if show: print("QUERY:",binascii.hexlify(data).decode(),file=sys.stderr)
            txid=struct.unpack(">H",data[:2])[0]
            r=build_fn(data,txid)
            if r is not None: c.sendall(struct.pack(">H",len(r))+r)
            c.close()
        s.close()
PYEOF
echo ok

