import sys, os, subprocess, threading, time, socket, struct
sys.path.insert(0,"/tmp/t")
from srv import *
KNOWN={1,2,5,6,12,13,15,16,28,29,33,35,41,44,52,257}
types=[t for t in list(range(0,300))+[32768,32769,65535,65534,65280,999,1234,60000] if t not in KNOWN]
idx=[0]
def build(data,txid):
    t=types[idx[0]]; idx[0]+=1
    r=Resp(); r.question("a.b",255,1)
    r.add("an","a.b",t,1,300,b"\x01")
    return r.build(txid)
th=threading.Thread(target=serve,args=(build,5353,len(types),"tcp",False),daemon=True); th.start()
time.sleep(0.3)
res={}
for t in types:
    p=subprocess.run(["/workspace/executable","a.b","ANY","-n","127.0.0.1:5353","--colour=never","-T"],capture_output=True,text=True,timeout=15)
    if p.returncode!=0: res[t]=("ERR",p.stderr.strip())
    else:
        n=p.stdout.split()[0]
        res[t]=("OK",n)
for t in types:
    k,v=res[t]
    if k=="ERR" or v!=str(t): print(t,k,v)
