import sys; sys.path.insert(0,"/tmp/t")
from run import *
import socket, struct
def mkf(flags, an=True, ns=False, ar=False, opt=False):
    def mk(data,txid):
        r=Resp(); r.flags=flags; r.question("a.b",1,1)
        if an: r.add("an","a.b",1,1,300,socket.inet_aton("1.2.3.4"))
        if ns: r.add("ns","b.",2,1,900,enc_name("ns1.b"))
        if ar: r.add("ar","ns1.b",1,1,900,socket.inet_aton("9.9.9.9"))
        if opt: r.add("ar","",41,1232,0,b"")
        return r.build(txid)
    return mk
for name,f,kw in [("NOERROR+answer",0x8180,{}),
                  ("NXDOMAIN",0x8183,{"an":False}),
                  ("SERVFAIL",0x8182,{"an":False}),
                  ("REFUSED",0x8185,{"an":False}),
                  ("FORMERR",0x8181,{"an":False}),
                  ("NOTIMP",0x8184,{"an":False}),
                  ("rcode6",0x8186,{"an":False}),
                  ("rcode15",0x818f,{"an":False}),
                  ("noans-noerror",0x8180,{"an":False}),
                  ("authority",0x8180,{"an":False,"ns":True}),
                  ("all-sections",0x8180,{"ns":True,"ar":True}),
                  ("with-opt",0x8180,{"opt":True}),
                  ]:
    p=go(mkf(f,**kw),["a.b","-n","127.0.0.1:5353","--colour=never"],show=False)
    print(f"### {name}: exit={p.returncode}")
    print("OUT:",repr(p.stdout))
    print("ERR:",repr(p.stderr))
