//! Helpers for turning raw bytes from the wire into printable text.

/// Renders a DNS character-string as a quoted, escaped string.
///
/// Bytes that fall outside the printable ASCII range get replaced with a
/// backslash followed by their decimal value, and the two characters that
/// would otherwise confuse the surrounding quotes get backslash-escaped.
pub fn quote_bytes(bytes: &[u8]) -> String {
    let mut result = String::with_capacity(bytes.len() + 2);
    result.push('"');
    for &byte in bytes {
        match byte {
            b'"' => result.push_str("\\\""),
            b'\\' => result.push_str("\\\\"),
            0x20..=0x7f => result.push(byte as char),
            _ => {
                result.push('\\');
                result.push_str(&byte.to_string());
            }
        }
    }
    result.push('"');
    result
}

/// Decodes wire bytes as text, replacing anything that is not valid UTF-8
/// with the replacement character.
pub fn lossy(bytes: &[u8]) -> String {
    String::from_utf8_lossy(bytes).into_owned()
}

/// Renders a byte string as lowercase hexadecimal.
pub fn hex(bytes: &[u8]) -> String {
    let mut result = String::with_capacity(bytes.len() * 2);
    for byte in bytes {
        result.push_str(&format!("{:02x}", byte));
    }
    result
}

