//! The DNS wire protocol: turning bytes into structs and back again.

use std::fmt;

use crate::record::{Record, OPT};
use crate::types::*;

/// How many compression pointers a single name is allowed to chase before we
/// decide the packet is trying to make us loop forever.
const RECURSION_LIMIT: usize = 8;

/// Something that went wrong while reading a packet off the wire.
#[derive(PartialEq, Debug)]
pub enum WireError {
    /// The packet ran out before we had finished reading a field.
    IO,

    /// A record’s stated length did not match the length its type requires.
    WrongRecordLength {
        stated_length: u16,
        mandated_length: MandatedLength,
    },

    /// A record has a version field we do not know how to interpret.
    WrongVersion {
        stated_version: u8,
        maximum_supported_version: u8,
    },

    /// A name kept pointing at other names.
    TooMuchRecursion(Vec<u16>),
}

/// The length a record type demands of its data.
#[derive(PartialEq, Debug, Copy, Clone)]
pub enum MandatedLength {
    /// The length has to be exactly this many bytes.
    Exactly(u16),

    /// The length has to be this many bytes or more.
    AtLeast(u16),
}

impl fmt::Display for WireError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::IO => {
                write!(f, "insufficient data")
            }
            Self::WrongRecordLength { stated_length, mandated_length: MandatedLength::Exactly(len) } => {
                write!(f, "record length should be {}, got {}", len, stated_length)
            }
            Self::WrongRecordLength { stated_length, mandated_length: MandatedLength::AtLeast(len) } => {
                write!(f, "record length should be at least {}, got {}", len, stated_length)
            }
            Self::WrongVersion { stated_version, maximum_supported_version } => {
                write!(f, "record specifies version {}, expected up to {}",
                       stated_version, maximum_supported_version)
            }
            Self::TooMuchRecursion(offsets) => {
                write!(f, "too much recursion: {:?}", offsets)
            }
        }
    }
}

/// A cursor that reads big-endian numbers and names out of a packet.
///
/// The whole packet is kept around even when a record’s data is being read,
/// because compression pointers can point anywhere within it.
pub struct Cursor<'a> {
    packet: &'a [u8],
    position: usize,
}

impl<'a> Cursor<'a> {
    pub fn new(packet: &'a [u8]) -> Self {
        Cursor { packet, position: 0 }
    }

    pub fn position(&self) -> usize {
        self.position
    }

    pub fn read_u8(&mut self) -> Result<u8, WireError> {
        match self.packet.get(self.position) {
            Some(byte) => {
                self.position += 1;
                Ok(*byte)
            }
            None => Err(WireError::IO),
        }
    }

    pub fn read_u16(&mut self) -> Result<u16, WireError> {
        let hi = u16::from(self.read_u8()?);
        let lo = u16::from(self.read_u8()?);
        Ok(hi << 8 | lo)
    }

    pub fn read_u32(&mut self) -> Result<u32, WireError> {
        let hi = u32::from(self.read_u16()?);
        let lo = u32::from(self.read_u16()?);
        Ok(hi << 16 | lo)
    }

    pub fn read_bytes(&mut self, amount: usize) -> Result<&'a [u8], WireError> {
        let end = self.position.checked_add(amount).ok_or(WireError::IO)?;
        match self.packet.get(self.position..end) {
            Some(slice) => {
                self.position = end;
                Ok(slice)
            }
            None => Err(WireError::IO),
        }
    }

    /// Reads a length-prefixed character-string.
    pub fn read_string(&mut self) -> Result<Vec<u8>, WireError> {
        let length = usize::from(self.read_u8()?);
        Ok(self.read_bytes(length)?.to_vec())
    }

    /// Reads a domain name, following any compression pointers.
    pub fn read_labels(&mut self) -> Result<Labels, WireError> {
        let mut labels = Labels::empty();
        let mut visited = Vec::new();

        loop {
            let byte = self.read_u8()?;

            if byte == 0 {
                return Ok(labels);
            } else if byte & 0b1100_0000 == 0b1100_0000 {
                let second = self.read_u8()?;
                let offset = (u16::from(byte & 0b0011_1111) << 8) | u16::from(second);

                if visited.len() >= RECURSION_LIMIT || visited.contains(&offset) {
                    return Err(WireError::TooMuchRecursion(visited));
                }
                visited.push(offset);

                let mut inner = Cursor { packet: self.packet, position: usize::from(offset) };
                loop {
                    let byte = inner.read_u8()?;
                    if byte == 0 {
                        return Ok(labels);
                    } else if byte & 0b1100_0000 == 0b1100_0000 {
                        let second = inner.read_u8()?;
                        let offset = (u16::from(byte & 0b0011_1111) << 8) | u16::from(second);
                        if visited.len() >= RECURSION_LIMIT || visited.contains(&offset) {
                            return Err(WireError::TooMuchRecursion(visited));
                        }
                        visited.push(offset);
                        inner.position = usize::from(offset);
                    } else {
                        let bytes = inner.read_bytes(usize::from(byte))?;
                        labels.push(byte, bytes);
                    }
                }
            } else {
                let bytes = self.read_bytes(usize::from(byte))?;
                labels.push(byte, bytes);
            }
        }
    }
}

/// The parsed form of a response packet.
#[derive(PartialEq, Debug)]
pub struct Response {
    pub transaction_id: u16,
    pub flags: Flags,
    pub queries: Vec<Query>,
    pub answers: Vec<Answer>,
    pub authorities: Vec<Answer>,
    pub additionals: Vec<Answer>,
}

/// One entry of a response’s question section.
#[derive(PartialEq, Debug)]
pub struct Query {
    pub qname: Labels,
    pub qtype: u16,
    pub qclass: QClass,
}

/// One record from one of a response’s three answer sections.
#[derive(PartialEq, Debug)]
pub enum Answer {
    /// An ordinary record with a name, class, and time-to-live.
    Standard {
        qname: Labels,
        qclass: QClass,
        ttl: u32,
        record: Record,
    },

    /// A pseudo-record carrying protocol extensions.
    Pseudo { qname: Labels, opt: OPT },
}

impl Response {
    /// Reads a response out of a buffer of bytes received from a server.
    pub fn from_bytes(bytes: &[u8]) -> Result<Self, WireError> {
        crate::log::info("dns::wire", "Parsing response");
        crate::log::trace("dns::wire", &format!("Bytes -> {:?}", bytes));

        let mut c = Cursor::new(bytes);

        let transaction_id = c.read_u16()?;
        crate::log::trace("dns::wire", &format!("Read txid -> {}", transaction_id));

        let flags = Flags::from_u16(c.read_u16()?);
        crate::log::trace("dns::wire", &format!("Read flags -> {:#?}", flags));

        let query_count = c.read_u16()?;
        let answer_count = c.read_u16()?;
        let authority_count = c.read_u16()?;
        let additional_count = c.read_u16()?;

        let mut queries = Vec::new();
        crate::log::debug("dns::wire", &format!("Reading {}x query from response", query_count));
        for _ in 0..query_count {
            let qname = c.read_labels()?;
            let (qtype, qclass) = read_type_and_class(&mut c)?;
            queries.push(Query { qname, qtype, qclass });
        }

        let mut answers = Vec::new();
        crate::log::debug("dns::wire", &format!("Reading {}x answer from response", answer_count));
        for _ in 0..answer_count {
            answers.push(Answer::from_bytes(&mut c)?);
        }

        let mut authorities = Vec::new();
        crate::log::debug("dns::wire", &format!("Reading {}x authority from response", authority_count));
        for _ in 0..authority_count {
            authorities.push(Answer::from_bytes(&mut c)?);
        }

        let mut additionals = Vec::new();
        crate::log::debug("dns::wire", &format!("Reading {}x additional answer from response", additional_count));
        for _ in 0..additional_count {
            additionals.push(Answer::from_bytes(&mut c)?);
        }

        Ok(Response { transaction_id, flags, queries, answers, authorities, additionals })
    }
}

fn read_type_and_class(c: &mut Cursor<'_>) -> Result<(u16, QClass), WireError> {
    let qtype = c.read_u16()?;
    crate::log::trace("dns::wire", &format!("Read qtype number -> {}", qtype));
    match crate::record::type_name(qtype) {
        Some(name) => crate::log::trace("dns::wire", &format!("Found qtype -> {}", name)),
        None => crate::log::trace("dns::wire", &format!("Found qtype -> {}", qtype)),
    }

    let qclass = QClass::from_u16(c.read_u16()?);
    crate::log::trace("dns::wire", &format!("Read qclass -> {}", crate::record::type_name(qtype).unwrap_or("?")));
    Ok((qtype, qclass))
}

impl Answer {
    fn from_bytes(c: &mut Cursor<'_>) -> Result<Self, WireError> {
        let qname = c.read_labels()?;
        let (qtype, qclass) = read_type_and_class(c)?;

        if qtype == OPT::TYPE_NUMBER {
            let opt = OPT::read(qclass.0, c)?;
            return Ok(Answer::Pseudo { qname, opt });
        }

        let ttl = c.read_u32()?;
        crate::log::trace("dns::wire", &format!("Read TTL -> {}", ttl));

        let length = c.read_u16()?;
        crate::log::trace("dns::wire", &format!("Read record length -> {}", length));

        let record = Record::read(qtype, length, c)?;
        Ok(Answer::Standard { qname, qclass, ttl, record })
    }
}

