//! Shared types that appear in both requests and responses.

use std::fmt;

/// A domain name, stored as the sequence of labels it was made of.
#[derive(PartialEq, Clone)]
pub struct Labels {
    pub segments: Vec<(u8, String)>,
}

impl Labels {
    /// A name with no labels at all: the DNS root.
    pub fn root() -> Self {
        Labels { segments: Vec::new() }
    }

    /// An empty name that is about to have labels pushed onto it.
    pub fn empty() -> Self {
        Labels { segments: Vec::new() }
    }

    /// Adds a label read off the wire.
    pub fn push(&mut self, length: u8, bytes: &[u8]) {
        self.segments.push((length, String::from_utf8_lossy(bytes).into_owned()));
    }

    /// Splits a user-provided domain name into labels, skipping the empty
    /// segments that leading, trailing, and doubled dots produce.
    pub fn encode(input: &str) -> Result<Self, LabelError> {
        let mut segments = Vec::new();

        for label in input.split('.') {
            if label.is_empty() {
                continue;
            }

            let encoded = crate::idna::to_ascii(label)?;
            if encoded.len() > 63 {
                return Err(LabelError::TooLong);
            }

            segments.push((encoded.len() as u8, encoded));
        }

        Ok(Labels { segments })
    }

    /// The bytes this name takes up in a packet, uncompressed.
    pub fn to_bytes(&self) -> Vec<u8> {
        let mut bytes = Vec::new();
        for (length, label) in &self.segments {
            bytes.push(*length);
            bytes.extend_from_slice(label.as_bytes());
        }
        bytes.push(0);
        bytes
    }
}

/// Something that stopped a user-provided name from being made into labels.
#[derive(PartialEq, Debug)]
pub enum LabelError {
    TooLong,
    Punycode,
}

