                }
            }
        }

        struct ErrorCode(u8);
        impl fmt::Debug for ErrorCode {
            fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
                match self.0 {
                    0 => f.write_str("None"),
                    1 => f.write_str("Some(\n        FormatError,\n    )"),
                    n => write!(f, "Some(\n        Other({}),\n    )", n),
                }
            }
        }

        f.debug_struct("Flags")
            .field("response", &self.response)
            .field("opcode", &Opcode(self.opcode))
            .field("authoritative", &self.authoritative)
            .field("truncated", &self.truncated)
            .field("recursion_desired", &self.recursion_desired)
            .field("recursion_available", &self.recursion_available)
            .field("authentic_data", &self.authentic_data)
            .field("checking_disabled", &self.checking_disabled)
            .field("error_code", &ErrorCode(self.error_code))
            .finish()
    }
}

