//! The record types that dog knows how to interpret.

use std::fmt;
use std::net::{Ipv4Addr, Ipv6Addr};

use crate::strings::{hex, lossy, quote_bytes};
use crate::types::Labels;
use crate::wire::{Cursor, MandatedLength, WireError};

/// How durations inside a record’s data should be rendered.
#[derive(PartialEq, Debug, Copy, Clone)]
pub struct TextFormat {
    pub format_durations: bool,
}

impl TextFormat {
    /// Renders a number of seconds, either as a duration or as itself.
    pub fn format_duration(self, seconds: u32) -> String {
        if self.format_durations {
            format_duration_hms(seconds)
        } else {
            seconds.to_string()
        }
    }
}

/// Renders a number of seconds as days, hours, minutes, and seconds.
pub fn format_duration_hms(seconds: u32) -> String {
    if seconds < 60 {
        format!("{}s", seconds)
    } else if seconds < 60 * 60 {
        format!("{}m{:02}s", seconds / 60, seconds % 60)
    } else if seconds < 60 * 60 * 24 {
        format!("{}h{:02}m{:02}s", seconds / 3600, (seconds % 3600) / 60, seconds % 60)
    } else {
        format!("{}d{}h{:02}m{:02}s",
                seconds / 86400,
                (seconds % 86400) / 3600,
                (seconds % 3600) / 60,
                seconds % 60)
    }
}

/// The names of every record type dog is able to send a request for, even
/// the ones whose responses it cannot make sense of.
static TYPE_NAMES: &[(u16, &str)] = &[
    (1, "A"),
    (2, "NS"),
    (5, "CNAME"),
    (6, "SOA"),
    (12, "PTR"),
    (13, "HINFO"),
    (15, "MX"),
    (16, "TXT"),
    (17, "RP"),
    (18, "AFSDB"),
    (24, "SIG"),
    (25, "KEY"),
    (28, "AAAA"),
    (29, "LOC"),
    (33, "SRV"),
    (35, "NAPTR"),
    (36, "KX"),
    (37, "CERT"),
    (39, "DNAME"),
    (41, "OPT"),
    (42, "APL"),
    (43, "DS"),
    (44, "SSHFP"),
    (45, "IPSECKEY"),
    (46, "RRSIG"),
    (47, "NSEC"),
    (48, "DNSKEEYE"),
    (49, "DHCID"),
    (50, "NSEC3"),
    (51, "NSEC3PARAM"),
    (52, "TLSA"),
    (53, "SMIMEA"),
    (55, "HIP"),
    (59, "CDS"),
    (60, "CDNSKEY"),
    (61, "OPENPGPKEY"),
    (62, "CSYNC"),
    (108, "EUI48"),
    (109, "EUI64"),
    (249, "TKEY"),
    (250, "TSIG"),
    (251, "IXFR"),
    (252, "AXFR"),
    (255, "ANY"),
    (256, "URI"),
    (257, "CAA"),
    (32768, "TA"),
    (32769, "DLV"),
];

/// Looks up the name of a type number.
pub fn type_name(number: u16) -> Option<&'static str> {
    TYPE_NAMES.iter().find(|(n, _)| *n == number).map(|(_, name)| *name)
}

/// Looks up the number of a type name, case-insensitively.
pub fn type_number(name: &str) -> Option<u16> {
    let upper = name.to_ascii_uppercase();
    TYPE_NAMES.iter().find(|(_, n)| *n == upper).map(|(number, _)| *number)
}

macro_rules! records {
    ($( $name:ident, $number:expr, $module:expr, $colour:expr; )*) => {
        /// A record read out of a response packet.
        #[derive(PartialEq, Debug)]
        pub enum Record {
            $( $name($name), )*

            /// A record of a type dog has no interpretation for.
            Other { type_number: u16, bytes: Vec<u8> },
        }

        impl Record {
            /// The name that gets shown in the type column.
            pub fn type_name(&self) -> String {
                match self {
                    $( Self::$name(_) => String::from(stringify!($name)), )*
                    Self::Other { type_number, .. } => {
                        match type_name(*type_number) {
                            Some(name) => String::from(name),
                            None => type_number.to_string(),
                        }
                    }
                }
            }

            /// A key naming the palette entry this record should be shown in.
            pub fn colour_name(&self) -> Option<&'static str> {
                match self {
                    $( Self::$name(_) => Some($colour), )*
                    Self::Other { .. } => None,
                }
            }

            /// A short human-readable rendering of this record’s data.
            pub fn summary(&self, format: TextFormat) -> String {
                match self {
                    $( Self::$name(r) => r.summary(format), )*
                    Self::Other { bytes, .. } => format!("{:?}", bytes),
                }
            }

            /// This record’s data as a JSON object.
            pub fn json(&self) -> String {
                match self {
                    $( Self::$name(r) => r.json(), )*
                    Self::Other { bytes, .. } => {
                        let numbers = bytes.iter().map(u8::to_string).collect::<Vec<_>>();
                        format!("{{\"bytes\":[{}]}}", numbers.join(","))
                    }
                }
            }

            /// This record’s type, as it appears in JSON output: a string for
            /// the types dog interprets, and a bare number otherwise.
            pub fn json_type(&self) -> String {
                match self {
                    $( Self::$name(_) => format!("{:?}", stringify!($name)), )*
                    Self::Other { type_number, .. } => type_number.to_string(),
                }
            }

            /// Reads the data of a record of the given type.
            pub fn read(qtype: u16, length: u16, c: &mut Cursor<'_>)
                -> Result<Self, WireError>
            {
                match qtype {
                    $(
                        $number => {
                            crate::log::info("dns::wire",
                                &format!("Parsing {} record (type {}, len {})",
                                         stringify!($name), qtype, length));
                            Ok(Self::$name($name::read(length, c)?))
                        }
                    )*
                    _ => {
                        let bytes = c.read_bytes(usize::from(length))?.to_vec();
                        Ok(Self::Other { type_number: qtype, bytes })
                    }
                }
            }

            /// The module name used when logging about this record type.
            #[allow(dead_code)]
            pub fn module(&self) -> &'static str {
                match self {
                    $( Self::$name(_) => $module, )*
                    Self::Other { .. } => "dns::wire",
                }
            }
        }
    };
}

records! {
    A,     1,   "dns::record::a",     "a";
    NS,    2,   "dns::record::ns",    "ns";
    CNAME, 5,   "dns::record::cname", "cname";
    SOA,   6,   "dns::record::soa",   "soa";
    PTR,   12,  "dns::record::ptr",   "ptr";
    HINFO, 13,  "dns::record::hinfo", "hinfo";
    MX,    15,  "dns::record::mx",    "mx";
    TXT,   16,  "dns::record::txt",   "txt";
    AAAA,  28,  "dns::record::aaaa",  "aaaa";
    LOC,   29,  "dns::record::loc",   "loc";
    SRV,   33,  "dns::record::srv",   "srv";
    NAPTR, 35,  "dns::record::naptr", "naptr";
    SSHFP, 44,  "dns::record::sshfp", "sshfp";
    TLSA,  52,  "dns::record::tlsa",  "tlsa";
    EUI48, 108, "dns::record::eui48", "eui48";
    EUI64, 109, "dns::record::eui64", "eui64";
    URI,   256, "dns::record::uri",   "uri";
    CAA,   257, "dns::record::caa",   "caa";
}

/// Rejects a record whose length is not what its type demands.
fn check_length(length: u16, mandated: MandatedLength) -> Result<(), WireError> {
    let ok = match mandated {
        MandatedLength::Exactly(l) => length == l,
        MandatedLength::AtLeast(l) => length >= l,
    };

    if ok {
        Ok(())
    } else {
        Err(WireError::WrongRecordLength { stated_length: length, mandated_length: mandated })
    }
}

/// Rejects a record whose data did not end exactly where it said it would.
fn check_consumed(length: u16, consumed: usize) -> Result<(), WireError> {
    if usize::from(length) == consumed {
        crate::log::trace("dns::wire", "Length is correct");
        Ok(())
    } else {
        Err(WireError::WrongDataLength { stated_length: length, length_after_labels: consumed })
    }
}

// ---- A ----

/// An IPv4 address.
#[derive(PartialEq, Debug)]
pub struct A {
    pub address: Ipv4Addr,
}

impl A {
    fn read(length: u16, c: &mut Cursor<'_>) -> Result<Self, WireError> {
        check_length(length, MandatedLength::Exactly(4))?;
        let bytes = c.read_bytes(4)?;
        let address = Ipv4Addr::new(bytes[0], bytes[1], bytes[2], bytes[3]);
        crate::log::trace("dns::record::a", &format!("Parsed IPv4 address -> {}", address));
        Ok(A { address })
    }

    fn summary(&self, _: TextFormat) -> String {
        self.address.to_string()
    }

    fn json(&self) -> String {
        format!("{{\"address\":{:?}}}", self.address.to_string())
    }
}

// ---- AAAA ----

/// An IPv6 address.
#[derive(PartialEq, Debug)]
pub struct AAAA {
    pub address: Ipv6Addr,
}

impl AAAA {
    fn read(length: u16, c: &mut Cursor<'_>) -> Result<Self, WireError> {
        check_length(length, MandatedLength::Exactly(16))?;
        let bytes = c.read_bytes(16)?;
        let mut octets = [0_u8; 16];
        octets.copy_from_slice(bytes);
        let address = Ipv6Addr::from(octets);
        crate::log::trace("dns::record::aaaa", &format!("Parsed IPv6 address -> {}", address));
        Ok(AAAA { address })
    }

    fn summary(&self, _: TextFormat) -> String {
        self.address.to_string()
    }

    fn json(&self) -> String {
        format!("{{\"address\":{:?}}}", self.address.to_string())
    }
}

// ---- CAA ----

/// A permitted certificate authority.
#[derive(PartialEq, Debug)]
pub struct CAA {
    pub critical: bool,
    pub tag: Vec<u8>,
    pub value: Vec<u8>,
}

impl CAA {
    fn read(length: u16, c: &mut Cursor<'_>) -> Result<Self, WireError> {
        let flags = c.read_u8()?;
        let critical = flags & 0b1000_0000 == 0b1000_0000;

        let tag_length = c.read_u8()?;
        let tag = c.read_bytes(usize::from(tag_length))?.to_vec();

        let remaining = usize::from(length).saturating_sub(2 + usize::from(tag_length));
        let value = c.read_bytes(remaining)?.to_vec();

        Ok(CAA { critical, tag, value })
    }

    fn summary(&self, _: TextFormat) -> String {
        format!("{} {} ({})",
                quote_bytes(&self.tag),
                quote_bytes(&self.value),
                if self.critical { "critical" } else { "non-critical" })
    }

    fn json(&self) -> String {
        format!("{{\"critical\":{},\"tag\":{},\"value\":{}}}",
                self.critical, json_string(&self.tag), json_string(&self.value))
    }
}

// ---- CNAME ----

/// A canonical name for a domain.
#[derive(PartialEq, Debug)]
pub struct CNAME {
    pub domain: Labels,
}

impl CNAME {
    fn read(length: u16, c: &mut Cursor<'_>) -> Result<Self, WireError> {
        let start = c.position();
        let domain = c.read_labels()?;
        check_consumed(length, c.position() - start)?;
        Ok(CNAME { domain })
    }

    fn summary(&self, _: TextFormat) -> String {
        format!("{:?}", self.domain.to_string())
    }

    fn json(&self) -> String {
