// ---- LOC ----

/// A geographical location.
#[derive(PartialEq, Debug)]
pub struct LOC {
    pub size: u8,
    pub horizontal_precision: u8,
    pub vertical_precision: u8,
    pub latitude: u32,
    pub longitude: u32,
    pub altitude: u32,
}

impl LOC {
    fn read(length: u16, c: &mut Cursor<'_>) -> Result<Self, WireError> {
        check_length(length, MandatedLength::Exactly(16))?;

        let version = c.read_u8()?;
        if version != 0 {
            return Err(WireError::WrongVersion {
                stated_version: version,
                maximum_supported_version: 0,
            });
        }

        let size = c.read_u8()?;
        let horizontal_precision = c.read_u8()?;
        let vertical_precision = c.read_u8()?;
        let latitude = c.read_u32()?;
        let longitude = c.read_u32()?;
        let altitude = c.read_u32()?;

        Ok(LOC { size, horizontal_precision, vertical_precision,
                 latitude, longitude, altitude })
    }

    fn size_string(&self) -> String {
        format!("{}e{}", self.size >> 4, self.size & 0b1111)
    }

    fn latitude_string(&self) -> String {
        angle(self.latitude, 'N', 'S')
    }

    fn longitude_string(&self) -> String {
        angle(self.longitude, 'E', 'W')
    }

    fn altitude_string(&self) -> String {
        format!("{}m", (f64::from(self.altitude) - 10_000_000.0) / 100.0)
    }

    fn summary(&self, _: TextFormat) -> String {
        format!("{} ({}, {}) ({}, {}, {})",
                self.size_string(),
                self.horizontal_precision,
                self.vertical_precision,
                self.latitude_string(),
                self.longitude_string(),
                self.altitude_string())
    }

    fn json(&self) -> String {
        format!("{{\"size\":{:?},\"precision\":{{\"horizontal\":{},\"vertical\":{}}},\
                 \"point\":{{\"latitude\":{:?},\"longitude\":{:?},\"altitude\":{:?}}}}}",
                self.size_string(),
                self.horizontal_precision,
                self.vertical_precision,
                self.latitude_string(),
                self.longitude_string(),
                self.altitude_string())
    }
}

/// Renders one of the two halves of a co-ordinate pair.
fn angle(value: u32, positive: char, negative: char) -> String {
    const EQUATOR: u32 = 0x8000_0000;

    let (thousandths, direction) = if value >= EQUATOR {
        (value - EQUATOR, positive)
    } else {
        (EQUATOR - value, negative)
    };

    let degrees = thousandths / 3_600_000;
    let minutes = (thousandths % 3_600_000) / 60_000;
    let seconds = f64::from(thousandths % 60_000) / 1000.0;

    format!("{}°{}′{}″ {}", degrees, minutes, seconds, direction)
}

