impl TLSA {
    fn read(length: u16, c: &mut Cursor<'_>) -> Result<Self, WireError> {
        check_length(length, MandatedLength::AtLeast(4))?;
        let certificate_usage = c.read_u8()?;
        let selector = c.read_u8()?;
        let matching_type = c.read_u8()?;
        let certificate_data = c.read_bytes(usize::from(length) - 3)?.to_vec();
        Ok(TLSA { certificate_usage, selector, matching_type, certificate_data })
    }

