// ---- TXT ----

/// Arbitrary textual information.
#[derive(PartialEq, Debug)]
pub struct TXT {
    pub messages: Vec<Vec<u8>>,
}

impl TXT {
    fn read(length: u16, c: &mut Cursor<'_>) -> Result<Self, WireError> {
        let mut messages = Vec::new();
        let mut remaining = usize::from(length);

        loop {
            let string_length = usize::from(c.read_u8()?);
            messages.push(c.read_bytes(string_length)?.to_vec());

            remaining = match remaining.checked_sub(string_length + 1) {
                Some(r) => r,
                None => return Err(WireError::IO),
            };

            if remaining == 0 {
                break;
            }
        }

        Ok(TXT { messages })
    }

    fn summary(&self, _: TextFormat) -> String {
        self.messages.iter().map(|m| quote_bytes(m)).collect::<Vec<_>>().join(", ")
    }

    fn json(&self) -> String {
        let messages = self.messages.iter()
                                    .map(|m| json_string(m))
                                    .collect::<Vec<_>>();
        format!("{{\"messages\":[{}]}}", messages.join(","))
    }
}

