        check_length(length, MandatedLength::AtLeast(5))?;
        let priority = c.read_u16()?;
        let weight = c.read_u16()?;
        let target = c.read_bytes(usize::from(length) - 4)?.to_vec();
        Ok(URI { priority, weight, target })
    }

    fn summary(&self, _: TextFormat) -> String {
        format!("{} {} {}", self.priority, self.weight, quote_bytes(&self.target))
    }

    fn json(&self) -> String {
        format!("{{\"priority\":{},\"weight\":{},\"target\":{}}}",
                self.priority, self.weight, json_string(&self.target))
    }
}

// ---- OPT ----

/// A pseudo-record carrying protocol extensions.
#[derive(PartialEq, Debug)]
pub struct OPT {
    pub udp_payload_size: u16,
    pub higher_bits: u8,
    pub edns0_version: u8,
    pub flags: u16,
    pub data: Vec<u8>,
}

impl OPT {
    pub const TYPE_NUMBER: u16 = 41;

    /// Reads an OPT record. Its class field has already been read, because
    /// OPT re-uses it as the sender’s UDP payload size.
    pub fn read(udp_payload_size: u16, c: &mut Cursor<'_>) -> Result<Self, WireError> {
        let higher_bits = c.read_u8()?;
        let edns0_version = c.read_u8()?;
        let flags = c.read_u16()?;
        let length = c.read_u16()?;
        let data = c.read_bytes(usize::from(length))?.to_vec();
        Ok(OPT { udp_payload_size, higher_bits, edns0_version, flags, data })
    }

    /// The bytes an outgoing OPT record takes up in a request.
    pub fn to_bytes(&self) -> Vec<u8> {
        let mut bytes = vec![0];
        bytes.extend_from_slice(&Self::TYPE_NUMBER.to_be_bytes());
        bytes.extend_from_slice(&self.udp_payload_size.to_be_bytes());
        bytes.push(self.higher_bits);
        bytes.push(self.edns0_version);
        bytes.extend_from_slice(&self.flags.to_be_bytes());
        bytes.extend_from_slice(&(self.data.len() as u16).to_be_bytes());
        bytes.extend_from_slice(&self.data);
        bytes
    }

    pub fn summary(&self) -> String {
        format!("{} {} {} {} {:?}", self.udp_payload_size, self.higher_bits,
                self.edns0_version, self.flags, self.data)
    }

    pub fn json(&self) -> String {
        let numbers = self.data.iter().map(u8::to_string).collect::<Vec<_>>();
        format!("{{\"version\":{},\"data\":[{}]}}", self.edns0_version, numbers.join(","))
    }
}

/// Renders wire bytes as a JSON string, replacing anything that is not valid
/// UTF-8 with the replacement character.
pub fn json_string(bytes: &[u8]) -> String {
    crate::json::string(&lossy(bytes))
}

impl fmt::Display for Record {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(&self.type_name())
    }
}

