//! The record types that dog knows how to interpret.

use std::fmt;
use std::net::{Ipv4Addr, Ipv6Addr};

use crate::strings::{hex, lossy, quote_bytes};
use crate::types::Labels;
use crate::wire::{Cursor, MandatedLength, WireError};

/// How durations inside a record’s data should be rendered.
#[derive(PartialEq, Debug, Copy, Clone)]
pub struct TextFormat {
    pub format_durations: bool,
}

impl TextFormat {
    /// Renders a number of seconds, either as a duration or as itself.
    pub fn format_duration(self, seconds: u32) -> String {
        if self.format_durations {
            format_duration_hms(seconds)
        } else {
            seconds.to_string()
        }
    }
}

/// Renders a number of seconds as days, hours, minutes, and seconds.
pub fn format_duration_hms(seconds: u32) -> String {
    if seconds < 60 {
        format!("{}s", seconds)
    } else if seconds < 60 * 60 {
        format!("{}m{:02}s", seconds / 60, seconds % 60)
    } else if seconds < 60 * 60 * 24 {
        format!("{}h{:02}m{:02}s", seconds / 3600, (seconds % 3600) / 60, seconds % 60)
    } else {
        format!("{}d{}h{:02}m{:02}s",
                seconds / 86400,
                (seconds % 86400) / 3600,
                (seconds % 3600) / 60,
                seconds % 60)
    }
}

/// The names of every record type dog is able to send a request for, even
/// the ones whose responses it cannot make sense of.
static TYPE_NAMES: &[(u16, &str)] = &[
    (1, "A"),
    (2, "NS"),
    (5, "CNAME"),
    (6, "SOA"),
    (12, "PTR"),
    (13, "HINFO"),
    (15, "MX"),
    (16, "TXT"),
    (17, "RP"),
    (18, "AFSDB"),
    (24, "SIG"),
    (25, "KEY"),
    (28, "AAAA"),
    (29, "LOC"),
    (33, "SRV"),
    (35, "NAPTR"),
    (36, "KX"),
    (37, "CERT"),
    (39, "DNAME"),
    (41, "OPT"),
    (42, "APL"),
    (43, "DS"),
    (44, "SSHFP"),
    (45, "IPSECKEY"),
    (46, "RRSIG"),
    (47, "NSEC"),
    (48, "DNSKEEYE"),
    (49, "DHCID"),
    (50, "NSEC3"),
    (51, "NSEC3PARAM"),
    (52, "TLSA"),
    (53, "SMIMEA"),
    (55, "HIP"),
    (59, "CDS"),
    (60, "CDNSKEY"),
    (61, "OPENPGPKEY"),
    (62, "CSYNC"),
    (108, "EUI48"),
    (109, "EUI64"),
    (249, "TKEY"),
    (250, "TSIG"),
    (251, "IXFR"),
    (252, "AXFR"),
    (255, "ANY"),
    (256, "URI"),
    (257, "CAA"),
    (32768, "TA"),
    (32769, "DLV"),
];

/// Looks up the name of a type number.
pub fn type_name(number: u16) -> Option<&'static str> {
    TYPE_NAMES.iter().find(|(n, _)| *n == number).map(|(_, name)| *name)
}

/// Looks up the number of a type name, case-insensitively.
pub fn type_number(name: &str) -> Option<u16> {
    let upper = name.to_ascii_uppercase();
    TYPE_NAMES.iter().find(|(_, n)| *n == upper).map(|(number, _)| *number)
}

macro_rules! records {
    ($( $name:ident, $number:expr, $module:expr, $colour:expr; )*) => {
        /// A record read out of a response packet.
        #[derive(PartialEq, Debug)]
        pub enum Record {
            $( $name($name), )*

            /// A record of a type dog has no interpretation for.
            Other { type_number: u16, bytes: Vec<u8> },
        }

        impl Record {
            /// The name that gets shown in the type column.
            pub fn type_name(&self) -> String {
                match self {
                    $( Self::$name(_) => String::from(stringify!($name)), )*
                    Self::Other { type_number, .. } => {
                        match type_name(*type_number) {
                            Some(name) => String::from(name),
                            None => type_number.to_string(),
                        }
                    }
                }
            }

            /// A key naming the palette entry this record should be shown in.
            pub fn colour_name(&self) -> Option<&'static str> {
                match self {
                    $( Self::$name(_) => Some($colour), )*
                    Self::Other { .. } => None,
                }
            }

            /// A short human-readable rendering of this record’s data.
            pub fn summary(&self, format: TextFormat) -> String {
                match self {
                    $( Self::$name(r) => r.summary(format), )*
                    Self::Other { bytes, .. } => format!("{:?}", bytes),
                }
            }

            /// This record’s data as a JSON object.
            pub fn json(&self) -> String {
                match self {
                    $( Self::$name(r) => r.json(), )*
                    Self::Other { bytes, .. } => {
                        let numbers = bytes.iter().map(u8::to_string).collect::<Vec<_>>();
                        format!("{{\"bytes\":[{}]}}", numbers.join(","))
                    }
                }
            }

            /// This record’s type, as it appears in JSON output: a string for
            /// the types dog interprets, and a bare number otherwise.
            pub fn json_type(&self) -> String {
                match self {
                    $( Self::$name(_) => format!("{:?}", stringify!($name)), )*
                    Self::Other { type_number, .. } => type_number.to_string(),
                }
            }

            /// Reads the data of a record of the given type.
            pub fn read(qtype: u16, length: u16, c: &mut Cursor<'_>)
                -> Result<Self, WireError>
            {
                match qtype {
                    $(
                        $number => {
                            crate::log::info("dns::wire",
                                &format!("Parsing {} record (type {}, len {})",
                                         stringify!($name), qtype, length));
                            Ok(Self::$name($name::read(length, c)?))
                        }
                    )*
                    _ => {
                        let bytes = c.read_bytes(usize::from(length))?.to_vec();
                        Ok(Self::Other { type_number: qtype, bytes })
                    }
                }
            }

            /// The module name used when logging about this record type.
            #[allow(dead_code)]
            pub fn module(&self) -> &'static str {
                match self {
                    $( Self::$name(_) => $module, )*
                    Self::Other { .. } => "dns::wire",
                }
            }
        }
    };
}

