// ---- CAA ----

/// A permitted certificate authority.
#[derive(PartialEq, Debug)]
pub struct CAA {
    pub critical: bool,
    pub tag: Vec<u8>,
    pub value: Vec<u8>,
}

impl CAA {
    fn read(length: u16, c: &mut Cursor<'_>) -> Result<Self, WireError> {
        let flags = c.read_u8()?;
        let critical = flags & 0b1000_0000 == 0b1000_0000;

        let tag_length = c.read_u8()?;
        let tag = c.read_bytes(usize::from(tag_length))?.to_vec();

        let remaining = usize::from(length).saturating_sub(2 + usize::from(tag_length));
        let value = c.read_bytes(remaining)?.to_vec();

        Ok(CAA { critical, tag, value })
    }

    fn summary(&self, _: TextFormat) -> String {
        format!("{} {} ({})",
                quote_bytes(&self.tag),
                quote_bytes(&self.value),
                if self.critical { "critical" } else { "non-critical" })
    }

    fn json(&self) -> String {
        format!("{{\"critical\":{},\"tag\":{},\"value\":{}}}",
                self.critical, json_string(&self.tag), json_string(&self.value))
    }
}

