//! An outgoing DNS request.

use crate::record::OPT;
use crate::types::{Flags, Labels, QClass};

/// A request that is about to be sent to a nameserver.
#[derive(PartialEq, Debug)]
pub struct Request {
    pub transaction_id: u16,
    pub flags: Flags,
    pub query: Query,
    pub additional: Option<OPT>,
}

/// The question a request is asking.
#[derive(PartialEq, Debug)]
pub struct Query {
    pub qname: Labels,
    pub qtype: u16,
    pub qclass: QClass,
}

/// Re-exported so that `dns::Response` keeps meaning the parsed kind.
pub type Response = crate::wire::Response;

impl Request {
    /// Serialises this request into the bytes that get sent over the wire.
    pub fn to_bytes(&self) -> Vec<u8> {
        let mut bytes = Vec::with_capacity(32);

        bytes.extend_from_slice(&self.transaction_id.to_be_bytes());
        bytes.extend_from_slice(&self.flags.to_u16().to_be_bytes());
        bytes.extend_from_slice(&1_u16.to_be_bytes());
        bytes.extend_from_slice(&0_u16.to_be_bytes());
        bytes.extend_from_slice(&0_u16.to_be_bytes());
        bytes.extend_from_slice(&u16::from(self.additional.is_some()).to_be_bytes());

        bytes.extend_from_slice(&self.query.qname.to_bytes());
        bytes.extend_from_slice(&self.query.qtype.to_be_bytes());
        bytes.extend_from_slice(&self.query.qclass.0.to_be_bytes());

        if let Some(opt) = &self.additional {
            bytes.extend_from_slice(&opt.to_bytes());
        }

        bytes
    }

    /// The two-byte length prefix that stream transports need, followed by
    /// the request itself.
    pub fn to_bytes_with_length(&self) -> Vec<u8> {
        let inner = self.to_bytes();
        let mut bytes = Vec::with_capacity(inner.len() + 2);
        bytes.extend_from_slice(&(inner.len() as u16).to_be_bytes());
        bytes.extend_from_slice(&inner);
        bytes
    }
}

