//! Emitting debugging output when the `DOG_DEBUG` variable is set.

use std::io::Write;
use std::sync::atomic::{AtomicU8, Ordering};

const OFF: u8 = 0;
const DEBUG: u8 = 1;
const TRACE: u8 = 2;

static LEVEL: AtomicU8 = AtomicU8::new(OFF);

/// Decides how noisy logging should be, based on the environment.
pub fn configure(variable: Option<&str>) {
    let level = match variable {
        None | Some("") => OFF,
        Some("trace") => TRACE,
        Some(_) => DEBUG,
    };

    LEVEL.store(level, Ordering::Relaxed);
}

fn enabled(minimum: u8) -> bool {
    LEVEL.load(Ordering::Relaxed) >= minimum
}

fn emit(level_colour: &str, level: &str, module: &str, message: &str) {
    let mut stderr = std::io::stderr();
    let _ = writeln!(stderr, "\x1b[38;5;243m[\x1b[0m\x1b[{}m{}\x1b[0m {}\x1b[38;5;243m]\x1b[0m {}",
                     level_colour, level, module, message);
}

pub fn info(module: &str, message: &str) {
    if enabled(DEBUG) {
        emit("36", "INFO", module, message);
    }
}

pub fn debug(module: &str, message: &str) {
    if enabled(DEBUG) {
        emit("34", "DEBUG", module, message);
    }
}

pub fn trace(module: &str, message: &str) {
    if enabled(TRACE) {
        emit("38;5;245", "TRACE", module, message);
    }
}

