//! Just enough JSON to write it out; dog never has to read any.

/// Renders a string as a JSON string literal, quotes included.
pub fn string(input: &str) -> String {
    let mut result = String::with_capacity(input.len() + 2);
    result.push('"');

    for c in input.chars() {
        match c {
            '"' => result.push_str("\\\""),
            '\\' => result.push_str("\\\\"),
            '\u{8}' => result.push_str("\\b"),
            '\u{9}' => result.push_str("\\t"),
            '\u{a}' => result.push_str("\\n"),
            '\u{c}' => result.push_str("\\f"),
            '\u{d}' => result.push_str("\\r"),
            c if (c as u32) < 0x20 => {
                result.push_str(&format!("\\u{:04x}", c as u32));
            }
            c => result.push(c),
        }
    }

    result.push('"');
    result
}

